import csv
rows = list(csv.DictReader(open('dataset/hospital_compensation_registry.csv')))
byid = {r['patient_id']: r for r in rows}
cols = ['patient_id','full_name','emergency_contact_patient_id','record_date','compensation_reason','policy_tier','coverage_status','documentation_status','direct_payment_usd']
print('=== SPECIAL COMPENSATION REASONS ===')
for r in rows:
    if r['compensation_reason'] in ('family support adjustment','bereavement compensation','life event claim'):
        print({c:r[c] for c in cols})
print()
print('=== INACTIVE coverage ===')
for r in rows:
    if r['coverage_status']=='inactive':
        print({c:r[c] for c in cols})
print()
print('=== INCOMPLETE documentation ===')
for r in rows:
    if r['documentation_status']=='incomplete':
        print({c:r[c] for c in cols})
"

