import csv
from collections import defaultdict, deque
rows = list(csv.DictReader(open('dataset/hospital_compensation_registry.csv')))
byid = {r['patient_id']: r for r in rows}
g = defaultdict(set)
for r in rows:
    a,b = r['patient_id'], r['emergency_contact_patient_id']
    if b in byid:
        g[a].add(b); g[b].add(a)

def comp(start):
    seen={start}; q=deque([start])
    while q:
        x=q.popleft()
        for y in g[x]:
            if y not in seen: seen.add(y); q.append(y)
    return seen

def line(pid, mark=''):
    r=byid[pid]
    hc = 'CLAIM   ' if r['compensation_reason'] else 'NO-CLAIM'
